def daggie(*, source: Directory | None = None, module_urls: list[str] | None = None, self_improve: str = 'off', session: _Session | None = None,) -> Daggie:
    """
    AI-powered Dagger CI specialist agent.

    Specializes in creating, explaining, and debugging Dagger CI modules
    and pipelines across all SDKs (Python, TypeScript, Go, Java).

    Accepts Git URLs of Dagger module repositories at runtime, clones them
    via
    dag.git(), and auto-discovers all modules within (by finding dagger-
    module.toml
    or, for Dagger 0.x modules, dagger.json files).
    You can also point to a specific module with the url#branch:path
    format.

    Pass your project as --source and optionally reference Dagger modules
    via
    --module-urls for the agent to learn from, or install the module and
    run
    `dagger agent` to work with Daggie interactively.

    Parameters
    ----------
    source:
        Project source directory
    module_urls:
        Git URLs of Dagger module repositories to clone and read for
        reference. Points to a repo root to auto-discover all modules
        (e.g. 'https://github.com/org/modules.git'), or to a specific
        module with 'url#branch:path' (e.g.
        'https://github.com/org/repo.git#main:my-module')
    self_improve:
        Self-improvement mode: 'off' (default), 'write' (update context
        file), 'commit' (update + git commit)
    """
    if not (source is None or isinstance(source, Directory)):
        raise _type_error("daggie", "source", source, "Directory | None")
    if not (module_urls is None or (isinstance(module_urls, list) and all(isinstance(_v0, str) for _v0 in module_urls))):
        raise _type_error("daggie", "module_urls", module_urls, "list[str] | None")
    if not (isinstance(self_improve, str)):
        raise _type_error("daggie", "self_improve", self_improve, "str")
    _args = [
        _Arg("source", source, None),
        _Arg("moduleUrls", module_urls, None),
        _Arg("selfImprove", self_improve, 'off'),
    ]
    return _client_root(Daggie, _TARGET, "daggie", _args, session=session)


__all__ = [
    "Daggie",
    "daggie",
]
